/// A Chain of Command class whose shapes broke COC001/002/003 before the shared
/// lexer landed: a NEW method with default parameters (no next, so no wrapper
/// rule applies), and a doc comment between the attribute and the first method.
[ExtensionOf(tableStr(CustTable))]
final class FixtureCustTable_Extension
{
}

Method.Source:
/// <summary>
/// A new method on the extension — not a wrapper, so the default parameter is
/// legal. COC001 fired here because it did not check for a call to next.
/// </summary>
/// <param name = "_accountNum">The account to find.</param>
/// <param name = "_forUpdate">Select for update.</param>
/// <returns>The record, or an empty buffer.</returns>
public static CustTable findByAccount(CustAccount _accountNum, boolean _forUpdate = false)
{
    CustTable custTable;

    custTable.selectForUpdate(_forUpdate);

    select firstonly custTable
        where custTable.AccountNum == _accountNum;

    return custTable;
}

/// A real wrapper: next is called, so the CoC rules apply in full.
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret && !this.CustGroup)
    {
        ret = checkFailed("@SYS12345");
    }

    return ret;
}
